#include <stdio.h>
#include <stdlib.h>
#include <gmp.h>
#include <stdbool.h>

// Function to check if a number is prime using GMP
bool isPrime(mpz_t number) {
    int result = mpz_probab_prime_p(number, 25); // 25 is the number of primality tests

    if (result == 0) {
        return false; // Definitely not prime
    } else if (result == 1) {
        return true; // Probably prime
    } else {
        return true; // Definitely prime
    }
}

int main() {
    // Initialize the large number as a string
    const char* num_str = ""; // Exemplo: Atribua o número diretamente aqui
    mpz_t possiblePrimeNumber;
    mpz_init_set_str(possiblePrimeNumber, num_str, 10);

    if (mpz_cmp_ui(possiblePrimeNumber, 0) == 0) {
        printf("0 is not a prime number.\n");
        mpz_clear(possiblePrimeNumber);
        return 0;
    }

    if (mpz_cmp_ui(possiblePrimeNumber, 0) < 0) {
        printf("Please enter a positive number.\n");
        mpz_clear(possiblePrimeNumber);
        return 1;
    }

    if (isPrime(possiblePrimeNumber)) {
        gmp_printf("%Zd is a prime number.\n", possiblePrimeNumber);
    } else {
        gmp_printf("%Zd is not a prime number.\n", possiblePrimeNumber);
    }

    mpz_clear(possiblePrimeNumber);
    return 0;
}
